let raw = $input.first().json.output || '';

// Extraer URL de QuickChart si existe
const urlMatch = raw.match(/https:\/\/quickchart\.io\/chart[^\s\)\]"']+/);
const imagenUrl = urlMatch ? urlMatch[0] : null;

// Limpiar la URL y el markdown del texto de respuesta
let respuesta = raw
  .replace(/\[Ver gráfico\]\([^\)]+\)/gi, '')
  .replace(/https:\/\/quickchart\.io\/chart[^\s\)\]"']+/g, '')
  .replace(/Aquí tienes el gráfico comparativo:/gi, '')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

return [{
  json: {
    respuesta:    respuesta,
    imagen_url:   imagenUrl,
    tiene_imagen: imagenUrl !== null,
    pregunta:     $('Foxy Contexto SQL').first().json.pregunta,
    sessionId:    $('Foxy Contexto SQL').first().json.sessionId,
    output:       respuesta
  }
}];

const respuesta = ($input.first().json.text || '').toLowerCase().trim();
const intencionClassifier = respuesta.includes('sql') ? 'sql' : 'conversacional';

const contexto = $('Foxy Contexto SQL').first().json;
const pregunta = (contexto.pregunta || '').toLowerCase().trim();

// Detección de confirmación INDEPENDIENTE del clasificador
// El clasificador no tiene memoria, así que no puede saber si hubo propuesta previa
const PATRON_CONFIRMACION = [
  'sí', 'si', 'dale', 'claro', 'hazlo', 'ok', 'vale', 'perfecto',
  'está bien', 'procede', 'adelante', 'muéstramelo', 'hagámoslo',
  'por favor', 'correcto', 'exacto', 'genial', 'listo', 'bueno',
  'claro que sí', 'por supuesto', 'sí por favor', 'sí, por favor',
  'muéstrame', 'hacemos eso', 'sí, hazlo', 'sí claro',
  'de acuerdo', 'sí, adelante', 'veamos', 'vamos', 'va',
  'sí, veamos', 'sí, claro', 'sí, dale', 'sí, perfecto',
  'hagamoslo', 'va pues', 'eso', 'a ver', 'show me', 'yes'
];

// Detectar confirmación solo por patrón de texto, SIN depender del clasificador
const esConfirmacion =
  pregunta.length <= 40 &&
  PATRON_CONFIRMACION.some(p =>
    pregunta === p ||
    pregunta === p + '.' ||
    pregunta === p + '!' ||
    pregunta.startsWith(p + ' ') ||
    pregunta.endsWith(' ' + p) ||
    pregunta === '¡' + p + '!'
  );

// Si es confirmación, FORZAR intención a sql para que se ejecute la propuesta
const intencion = esConfirmacion ? 'sql' : intencionClassifier;

return [{
  json: {
    ...contexto,
    intencion:       intencion,
    es_confirmacion: esConfirmacion
  }
}];

const contexto = $('Foxy Contexto SQL').first().json;

// Extraer Query puede no existir en flujos conversacionales
let querySql = '';
try {
  querySql = $('Extraer Query').first()?.json?.query || '';
} catch(e) {
  querySql = '';
}

const sessionId  = (contexto.sessionId  || 'session_default').replace(/'/g, "''");
const userId     = (contexto.userId     || 'user_default').replace(/'/g, "''");
const pregunta   = (contexto.pregunta   || '').replace(/'/g, "''");
const queryClean = querySql.replace(/'/g, "''");
const totalFilas = $json.total_filas || 0;
const fueraAlcance = $json.fuera_alcance || false;

return [{
  json: {
    sessionId,
    userId,
    pregunta,
    querySql: queryClean,
    totalFilas,
    fueraAlcance
  }
}];

return [{
  json: {
    datos:           [],
    total_filas:     0,
    pregunta:        $json.pregunta,
    sessionId:       $json.sessionId,
    userId:          $json.userId,
    es_confirmacion: false,
    fuera_alcance:   false,
    es_conversacional: true
  }
}];

const extraerJson = $('Extraer Query').first().json;

// Si el input viene del path fuera_alcance (If → Limitar Datos directo)
// el $input puede ser el resultado de Validar Query con fuera_alcance=true
// Detectar ese caso para propagar correctamente
const firstInput = $input.first().json;
const esFueraAlcance = firstInput.fuera_alcance === true && firstInput.query === null;

if (esFueraAlcance) {
  return [{
    json: {
