      total_filas:     0,
      pregunta:        extraerJson.pregunta,
      sessionId:       extraerJson.sessionId,
      es_confirmacion: extraerJson.es_confirmacion || false,
      fuera_alcance:   true
    }
  }];
}

// Path normal: datos del ejecutar_SQL
const items = $input.all().map(i => i.json);
const limitado = items.slice(0, 50);

return [{
  json: {
    datos:           limitado,
    total_filas:     items.length,
    pregunta:        extraerJson.pregunta,
    sessionId:       extraerJson.sessionId,
    es_confirmacion: extraerJson.es_confirmacion || false,
    fuera_alcance:   false
  }
}];

