// Si es fuera de alcance, pasar directo sin validar SQL
if ($json.fuera_alcance === true) {
  return [{ json: $json }];
}

const query = $json.query?.toString() || '';
const queryUpper = query.toUpperCase();

// Blacklist de operaciones prohibidas
const blacklist = [
  'INSERT','UPDATE','DELETE','DROP','TRUNCATE',
  'ALTER','CREATE','EXEC','EXECUTE','XP_','SP_',
  'SHUTDOWN','OPENROWSET','BULK','GRANT','REVOKE',
  'DENY','BACKUP','RESTORE','DBCC'
];
const bloqueado = blacklist.find(w => queryUpper.includes(w));
if (bloqueado) throw new Error(`Operación no permitida: ${bloqueado}`);

// Validar filtro obligatorio de Rectoría — con excepción para Oferta_Activa
const esOfertaActiva = queryUpper.includes('OFERTA_ACTIVA');
const tieneRectoria = queryUpper.includes('RECTORÍA') || queryUpper.includes('RECTORIA');
if (!tieneRectoria && !esOfertaActiva) {
  throw new Error('El query no incluye el filtro obligatorio de Rectoría.');
}

// Prohibir acceso a tablas del sistema
const sistemaTables = [
  'SYS.','SYSOBJECTS','SYSCOLUMNS','INFORMATION_SCHEMA',
  'SYS.TABLES','SYS.COLUMNS','SYS.DATABASES',
  'MASTER','MSDB','TEMPDB','MODEL'
];
const tablaBloqueada = sistemaTables.find(t => queryUpper.includes(t));
if (tablaBloqueada) throw new Error(`Acceso no permitido: ${tablaBloqueada}`);

// Solo permitir las 5 tablas de Foxy
const tablasPermitidas = [
  'POBLACION_ESTUDIANTIL',
  'CARACTERIZACION_ESTUDIANTES',
  'INDICADORES_PROYECCIONES',
  'PROYECCION_ESTUDIANTES',
  'OFERTA_ACTIVA'
];
const tieneTablaPermitida = tablasPermitidas.some(t => queryUpper.includes(t));
if (!tieneTablaPermitida) throw new Error('El query no referencia ninguna tabla autorizada de Foxy.');

// Prohibir comentarios maliciosos
if (queryUpper.includes('--') || queryUpper.includes('/*')) {
  throw new Error('Comentarios SQL no permitidos.');
}

return [{ json: $json }];

const item = $('ejecutar_query').first().json;
const output = item.output || item.text || item.response || JSON.stringify(item);

// Propagar flags desde pipeline anterior
const esConfirmacion    = $('Code in JavaScript1').first().json.es_confirmacion || false;
const preguntaOriginal  = $('Code in JavaScript1').first().json.pregunta_original
                          || $('Code in JavaScript1').first().json.pregunta
                          || $('Foxy Contexto SQL').first().json.pregunta;

// Detectar fuera de alcance
if (output.includes('FUERA_DE_ALCANCE')) {
  return [{
    json: {
      query:             null,
      fuera_alcance:     true,
      es_confirmacion:   esConfirmacion,
      pregunta:          preguntaOriginal,
      sessionId:         $('Foxy Contexto SQL').first().json.sessionId,
      userId:            $('Foxy Contexto SQL').first().json.userId
    }
  }];
}

// Extraer bloque SQL
let query = null;
const sqlBlock = output.match(/```sql\s*([\s\S]*?)```/i);
if (sqlBlock) {
  query = sqlBlock[1].trim();
} else {
  const selectMatch = output.match(/(SELECT[\s\S]+)/i);
  if (selectMatch) {
    query = selectMatch[1].split('```')[0].trim();
  }
}

if (query) {
  query = query.replace(/\\n/g, '\n').trim();
}

if (!query || !query.toUpperCase().includes('SELECT')) {
  throw new Error('No se encontró un SELECT válido en: ' + output);
}

return [{
  json: {
    query:             query,
    fuera_alcance:     false,
    es_confirmacion:   esConfirmacion,
    pregunta:          preguntaOriginal,
    sessionId:         $('Foxy Contexto SQL').first().json.sessionId,
    userId:            $('Foxy Contexto SQL').first().json.userId
  }
}];

// Contexto base de la clasificación
const contexto = $('Code in JavaScript1').first().json;

// Si NO es confirmación, pasar sin modificar
if (!contexto.es_confirmacion) {
  return [{ json: contexto }];
}

// ── Extraer última respuesta del asistente del historial ──────────────────
let ultimaRespuestaAsistente = '';
try {
  const rows = $input.all().map(i => i.json).filter(r => r && r.message);

  for (const row of rows) {
    let msg;
    try {
      msg = typeof row.message === 'string' ? JSON.parse(row.message) : row.message;
    } catch(e) { continue; }

    // El nodo memoryPostgresChat guarda { type: 'ai'|'human', data: { content } }
    const tipo = msg.type || (msg.data && msg.data.type) || '';
    if (tipo === 'ai' || tipo === 'AIMessage') {
      const content = (msg.data && msg.data.content) || msg.content || '';
      if (content && content.length > 10) {
        ultimaRespuestaAsistente = content;
        break; // Orden DESC → el primero encontrado es el más reciente
      }
    }
  }
} catch(eHist) {
  // Si falla la lectura del historial, usar fallback con instrucción para el agente
  return [{ json: {
    ...contexto,
    pregunta: `[CONFIRMACIÓN SIN CONTEXTO EXPLÍCITO]\nEl usuario respondió "${contexto.pregunta}" a tu última sugerencia.\nRevisa tu historial de conversación, identifica qué propusiste y ejecútalo.\nSi no encuentras propuesta previa, pregunta al usuario qué desea consultar.`,
    pregunta_original: contexto.pregunta
  }}];
}

if (!ultimaRespuestaAsistente) {
  // Sin historial legible → fallback con instrucción para usar memoria del agente
  return [{ json: {
    ...contexto,
    pregunta: `[CONFIRMACIÓN SIN CONTEXTO EXPLÍCITO]\nEl usuario respondió "${contexto.pregunta}" a tu última sugerencia.\nRevisa tu historial de conversación, identifica qué propusiste y ejecútalo.\nSi no encuentras propuesta previa, pregunta al usuario qué desea consultar.`,
    pregunta_original: contexto.pregunta
  }}];
}

// ── Construir pregunta enriquecida ────────────────────────────────────────
const propuesta = ultimaRespuestaAsistente.substring(0, 800);

const preguntaEnriquecida = `[CONFIRMACIÓN DE PROPUESTA]
El usuario respondió "${contexto.pregunta}" confirmando esta propuesta del asistente:

"${propuesta}"

INSTRUCCIÓN PARA EL GENERADOR SQL:
Analiza la propuesta anterior e identifica exactamente qué análisis ofreció el asistente.
Genera el SQL que cumpla esa propuesta. Reglas de traducción:
- "evolución", "cómo ha evolucionado", "tendencia", "por año", "últimos años"
  → GROUP BY Año ORDER BY Año ASC con las mismas métricas de la consulta previa
- "por programa" o "programas" → GROUP BY [Programa Académico]
- "por facultad"               → GROUP BY Facultad
- "por sede"                   → GROUP BY Sede
- "por modalidad"              → GROUP BY Modalidad
- "por Centro Universitario"   → GROUP BY [Centro Universitario]
- "distribución"               → GROUP BY la dimensión mencionada

Aplica los mismos filtros de la consulta anterior (Rectoría = 'Bogotá', mismo año o rango).
NUNCA respondas FUERA_DE_ALCANCE para una confirmación válida de propuesta.
NUNCA pidas más contexto. Genera el SQL directamente.`;

return [{
  json: {
    ...contexto,
    pregunta:          preguntaEnriquecida,
    pregunta_original: contexto.pregunta
  }
}];
